const http = require('http');
const https = require('https');

const body = $input.first().json.body || $input.first().json;
const event = body.event || '';
const model = body.model || body.payload?.model || {};
const actorId = body.actorId || body.payload?.actorId || '';

const COLLECTION_ID = $env.PM_OUTLINE_COLLECTION_ID;
const GILBERT_USER_ID = $env.GILBERT_OUTLINE_USER_ID;
const OUTLINE_API_KEY = $env.OUTLINE_GILBERT_API_KEY;

// --- Validation checks ---

// 1. Only process document events
if (!event.startsWith('documents.')) {
  return [{ json: { skip: true, reason: `Not a document event: ${event}` } }];
}

// 2. Only process update/create/delete/move
const validEvents = ['documents.update', 'documents.create', 'documents.delete', 'documents.move'];
if (!validEvents.includes(event)) {
  return [{ json: { skip: true, reason: `Unsupported event: ${event}` } }];
}

// 3. Collection check
const collectionId = model.collectionId || '';
if (collectionId !== COLLECTION_ID) {
  return [{ json: { skip: true, reason: `Wrong collection: ${collectionId}` } }];
}

// 4. Actor check — skip Gilbert's own edits
if (actorId === GILBERT_USER_ID) {
  return [{ json: { skip: true, reason: 'Edit by Gilbert — skipping to prevent loop' } }];
}

// 5. Skip archived docs
const archivedAt = model.archivedAt || null;
if (archivedAt) {
  return [{ json: { skip: true, reason: 'Document is archived — skipping' } }];
}

const docId = model.id || '';
const docTitle = model.title || 'Untitled';
const docText = model.text || '';
const parentDocumentId = model.parentDocumentId || null;

// Escape user-controllable IDs for SQL interpolation
const escapedDocId = docId.replace(/'/g, "''");
const escapedParentDocId = parentDocumentId ? parentDocumentId.replace(/'/g, "''") : null;

// HTTP helper
function httpReq(options, postData) {
  return new Promise((resolve, reject) => {
    const lib = options.protocol === 'https:' ? https : http;
    const req = lib.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        try { resolve({ status: res.statusCode, data: JSON.parse(body) }); }
        catch { resolve({ status: res.statusCode, data: body }); }
      });
    });
    req.on('error', reject);
    req.setTimeout(30000, () => { req.destroy(); reject(new Error('timeout')); });
    if (postData) req.write(postData);
    req.end();
  });
}

async function dbQuery(sql) {
  const execData = JSON.stringify({
    Cmd: ['sh', '-c', `PGPASSWORD=$POSTGRES_PASSWORD psql -U sovereign -d gilbert -t -A -c "${sql.replace(/"/g, '\\"')}"`],
    AttachStdout: true, AttachStderr: true, Tty: false
  });
  const execCreate = await httpReq({
    socketPath: '/var/run/docker.sock',
    path: '/v1.41/containers/sovereign-stack-postgres-1/exec',
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(execData) }
  }, execData);
  if (!execCreate.data?.Id) return '';
  const startData = JSON.stringify({ Detach: false, Tty: false });
  const rawResult = await new Promise((resolve, reject) => {
    const req = http.request({
      socketPath: '/var/run/docker.sock',
      path: `/v1.41/exec/${execCreate.data.Id}/start`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(startData) }
    }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve(Buffer.concat(chunks)));
    });
    req.on('error', reject);
    req.setTimeout(30000, () => { req.destroy(); reject(new Error('timeout')); });
    req.write(startData);
    req.end();
  });
  let text = '';
  let offset = 0;
  while (offset + 8 <= rawResult.length) {
    const frameSize = rawResult.readUInt32BE(offset + 4);
    offset += 8;
    if (frameSize > 0 && offset + frameSize <= rawResult.length) {
      text += rawResult.slice(offset, offset + frameSize).toString('utf8');
      offset += frameSize;
    } else { break; }
  }
  if (!text && rawResult.length > 8) {
    text = rawResult.toString('utf8').replace(/[\x00-\x08]/g, '');
  }
  return text.trim();
}

async function outlineApi(endpoint, apiBody) {
  const data = JSON.stringify(apiBody);
  return httpReq({
    hostname: 'outline',
    port: 3000,
    path: `/api/${endpoint}`,
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${OUTLINE_API_KEY}`,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(data)
    }
  }, data);
}

// --- Concurrency lock ---
const execId = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
const lockSql = `INSERT INTO execution_locks (workflow_id, locked_at, execution_id) VALUES (20, NOW(), '${execId}') ON CONFLICT (workflow_id) DO UPDATE SET locked_at = NOW(), execution_id = '${execId}' WHERE execution_locks.locked_at < NOW() - interval '10 minutes' RETURNING workflow_id`;
const lockResult = (await dbQuery(lockSql)).trim();
if (!lockResult.startsWith('20')) {
  return [{ json: { skip: true, reason: 'Another WF20 execution in progress' } }];
}

// --- hasChildren detection for create/update ---
let hasChildren = false;
if (event === 'documents.create' || event === 'documents.update') {
  try {
    const childResp = await outlineApi('documents.list', {
      parentDocumentId: docId,
      limit: 1
    });
    if (childResp.status === 200 && childResp.data?.data && childResp.data.data.length > 0) {
      hasChildren = true;
    }
  } catch {
    // If API fails, assume no children — safer default
  }
}

// 5. Handle move events
if (event === 'documents.move') {
  const syncRow = await dbQuery(
    `SELECT file_path, outline_parent_doc_id FROM sync_state WHERE outline_doc_id = '${escapedDocId}'`
  );

  if (!syncRow || !syncRow.trim()) {
    await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
    return [{ json: { skip: true, reason: 'Move event for untracked doc' } }];
  }

  const parts = syncRow.split('|');
  const oldParentDocId = parts[1] || null;

  // Skip if parent hasn't actually changed
  if (parentDocumentId === oldParentDocId) {
    await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
    return [{ json: { skip: true, reason: 'Parent unchanged — no-op move' } }];
  }

  // Check if moved doc has children (needed for subtree move)
  let moveHasChildren = false;
  try {
    const childResp = await outlineApi('documents.list', {
      parentDocumentId: docId,
      limit: 1
    });
    if (childResp.status === 200 && childResp.data?.data && childResp.data.data.length > 0) {
      moveHasChildren = true;
    }
  } catch { /* default false */ }

  await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
  return [{ json: {
    skip: false,
    action: 'move',
    doc_id: docId,
    title: docTitle,
    text: docText,
    parent_document_id: parentDocumentId,
    old_parent_document_id: oldParentDocId,
    has_children: moveHasChildren,
    event
  } }];
}

// 6. Sync lock check (for update/create/delete)
const syncRow = await dbQuery(
  `SELECT file_path, file_sha, sync_lock, sync_origin, is_pdf, content_hash FROM sync_state WHERE outline_doc_id = '${escapedDocId}'`
);

let githubPath = null;
let fileSha = null;
let isPdf = false;
let existingHash = null;
let isNewDoc = false;

if (syncRow && syncRow.trim()) {
  const parts = syncRow.split('|');
  githubPath = parts[0] || null;
  fileSha = parts[1] || null;
  const lockTime = parts[2] || null;
  const lockOrigin = parts[3] || null;
  isPdf = parts[4] === 't';
  existingHash = parts[5] || null;

  // Skip PDFs
  if (isPdf) {
    await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
    return [{ json: { skip: true, reason: 'PDF file — no reverse sync' } }];
  }

  // Sync lock check
  if ((lockOrigin === 'github' || lockOrigin === 'confluence') && lockTime) {
    const lockAge = Date.now() - new Date(lockTime).getTime();
    if (lockAge < 30000) {
      await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
      return [{ json: { skip: true, reason: `sync_lock active (${lockOrigin} origin, <30s)` } }];
    }
  }
} else {
  // New document — not yet tracked in sync_state
  if (event === 'documents.delete') {
    await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
    return [{ json: { skip: true, reason: 'Delete event for untracked doc — nothing to do' } }];
  }
  isNewDoc = true;
}

// 7. Content hash comparison for updates
function contentHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const chr = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + chr;
    hash |= 0;
  }
  return 'h' + Math.abs(hash).toString(36) + '_' + str.length;
}

if (!isNewDoc && event === 'documents.update') {
  const newHash = contentHash(docText);
  if (existingHash && existingHash === newHash) {
    await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
    return [{ json: { skip: true, reason: 'Content hash unchanged — no real change' } }];
  }
}

let action = 'update';
if (event === 'documents.create' || isNewDoc) action = 'create';
if (event === 'documents.delete') action = 'delete';

await dbQuery("DELETE FROM execution_locks WHERE workflow_id = 20");
return [{ json: {
  skip: false,
  action,
  doc_id: docId,
  title: docTitle,
  text: docText,
  github_path: githubPath,
  file_sha: fileSha,
  is_new_doc: isNewDoc,
  parent_document_id: parentDocumentId,
  has_children: hasChildren,
  event
} }];

