function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

function chunkText(chunkInput, maxLen = 1500, overlap = 200) {
  if (chunkInput.length <= maxLen) return [chunkInput];
  const chunks = [];
  let start = 0;
  while (start < chunkInput.length) {
    chunks.push(chunkInput.substring(start, start + maxLen));
    start += maxLen - overlap;
  }
  return chunks;
}

