// --- sanitizeTitle: preserves original casing, replaces OS-invalid chars ---
function sanitizeTitle(rawTitle) {
  return (rawTitle || 'Untitled')
    .replace(/[\/\\:*?"<>|]/g, '-')  // Replace OS-invalid chars with hyphen
    .replace(/\s+/g, ' ')            // Normalize whitespace
    .trim()
    .substring(0, 100);
}

// --- NEW: Resolve nested file path ---
async function resolveFilePath(docId, docTitle, parentDocId, docHasChildren) {
  const escapedRepo = repo.replace(/'/g, "''");
  const escapedId = docId.replace(/'/g, "''");

  // First: check sync_state for existing path
  const existingPath = await dbQuery(
    `SELECT file_path FROM sync_state WHERE repo = '${escapedRepo}' AND outline_doc_id = '${escapedId}'`
  );
  if (existingPath && existingPath.trim() && existingPath.trim().startsWith('Wiki/')) {
    return existingPath.trim();
  }

  // New doc: build nested path from parent chain
  const safeName = sanitizeTitle(docTitle);
  let basePath;

  if (parentDocId) {
    // Look up parent's file_path in sync_state
    const parentRow = await dbQuery(
      `SELECT file_path FROM sync_state WHERE repo = '${escapedRepo}' AND outline_doc_id = '${parentDocId.replace(/'/g, "''")}'`
    );

    if (parentRow && parentRow.trim()) {
      const parentPath = parentRow.trim();
      if (parentPath.endsWith('/_index.md')) {
        // Parent is already a folder — put child in that folder
        const parentFolder = parentPath.replace(/\/_index\.md$/, '');
        basePath = parentFolder;
      } else if (parentPath.endsWith('.md')) {
        // Parent is a leaf file — needs migration to folder/_index.md
        await migrateLeafToParent(parentDocId, parentPath);
        const parentFolder = parentPath.replace(/\.md$/, '');
        basePath = parentFolder;
      } else {
        basePath = 'Wiki';
      }
    } else {
      // Parent not in sync_state — walk up Outline parent chain
      basePath = await resolveParentPath(parentDocId);
    }
  } else {
    // Root-level doc
    basePath = 'Wiki';
  }

  // If doc has children → folder/_index.md, otherwise → .md
  if (docHasChildren) {
    return `${basePath}/${safeName}/_index.md`;
  } else {
    return `${basePath}/${safeName}.md`;
  }
}

// --- Walk up Outline parent chain to build path ---
async function resolveParentPath(docId) {
  const escapedRepo = repo.replace(/'/g, "''");
  // Try sync_state first
  const row = await dbQuery(
    `SELECT file_path FROM sync_state WHERE repo = '${escapedRepo}' AND outline_doc_id = '${docId.replace(/'/g, "''")}'`
  );
  if (row && row.trim()) {
    const p = row.trim();
    if (p.endsWith('/_index.md')) return p.replace(/\/_index\.md$/, '');
    if (p.endsWith('.md')) return p.replace(/\.md$/, '');
    return p;
  }

  // Fetch doc info from Outline
  const resp = await outlineApi('documents.info', { id: docId });
  if (resp.status !== 200 || !resp.data?.data) return 'Wiki';

  const doc = resp.data.data;
  const safeName = sanitizeTitle(doc.title);

  if (!doc.parentDocumentId) {
    return `Wiki/${safeName}`;
  }

  const parentBase = await resolveParentPath(doc.parentDocumentId);
  return `${parentBase}/${safeName}`;
}

// --- Migrate leaf .md to folder/_index.md ---
async function migrateLeafToParent(parentDocId, currentPath) {
  const escapedRepo = repo.replace(/'/g, "''");
  const escapedPath = currentPath.replace(/'/g, "''");
  const encodedPath = encodeURIComponent(currentPath).replace(/%2F/g, '/');

  // Fetch current content from GitHub
  const currentFile = await ghApi(`/repos/${repo}/contents/${encodedPath}?ref=main`);
  if (currentFile.status !== 200) return;

  const currentSha = currentFile.data?.sha;
  const contentBase64 = currentFile.data?.content || '';

  // New path: same base folder + /_index.md
  const newFolder = currentPath.replace(/\.md$/, '');
  const newPath = `${newFolder}/_index.md`;
  const encodedNewPath = encodeURIComponent(newPath).replace(/%2F/g, '/');

  // Create _index.md with the content
  const createResp = await ghApi(`/repos/${repo}/contents/${encodedNewPath}`, 'PUT', {
    message: `[sync] Migrate to folder: ${newFolder}`,
    content: contentBase64
  });

  if (createResp.status === 200 || createResp.status === 201) {
    // Delete old leaf file
    await ghApi(`/repos/${repo}/contents/${encodedPath}`, 'DELETE', {
      message: `[sync] Remove leaf (migrated to _index.md): ${currentPath}`,
      sha: currentSha
    });

    // Update sync_state
    const newSha = createResp.data?.content?.sha || '';
    const newPathEscaped = newPath.replace(/'/g, "''");
    await dbQuery(
      `UPDATE sync_state SET file_path = '${newPathEscaped}', file_sha = '${newSha}' WHERE repo = '${escapedRepo}' AND file_path = '${escapedPath}'`
    );
  }
}

// --- Build _tree.yaml from Outline collection structure ---
async function buildTreeYaml() {
  // Fetch ALL docs in the collection from Outline
  let allDocs = [];
  let fetchOffset = 0;
  const fetchLimit = 100;

  while (true) {
    const resp = await outlineApi('documents.list', {
      collectionId: COLLECTION_ID,
      limit: fetchLimit,
      offset: fetchOffset,
      statusFilter: ['published']
    });
    if (resp.status !== 200 || !resp.data?.data) break;
    const docs = resp.data.data;
    if (docs.length === 0) break;
    allDocs = allDocs.concat(docs);
    fetchOffset += docs.length;
    if (docs.length < fetchLimit) break;
  }

  // Also fetch sync_state to get file paths and confluence_ids
  const stateRows = await dbQuery(
    `SELECT outline_doc_id, file_path, confluence_page_id FROM sync_state WHERE repo = '${repo.replace(/'/g, "''")}' AND file_path LIKE 'Wiki/%.md'`
  );
  const stateMap = {};
  if (stateRows && stateRows.trim()) {
    for (const row of stateRows.split('\n')) {
      if (!row.trim()) continue;
      const [oid, fp, cid] = row.split('|');
      if (oid) stateMap[oid.trim()] = { file_path: (fp || '').trim(), confluence_page_id: (cid || '').trim() };
    }
  }

  // Build parent->children map
  const docMap = {};
  const rootDocs = [];

  for (const doc of allDocs) {
    docMap[doc.id] = {
      id: doc.id,
      title: doc.title || 'Untitled',
      parentDocumentId: doc.parentDocumentId || null,
      children: []
    };
  }

  for (const doc of allDocs) {
    if (doc.parentDocumentId && docMap[doc.parentDocumentId]) {
      docMap[doc.parentDocumentId].children.push(docMap[doc.id]);
    } else {
      rootDocs.push(docMap[doc.id]);
    }
  }

  // Sort children alphabetically by title at each level
  function sortChildren(node) {
    node.children.sort((a, b) => a.title.localeCompare(b.title));
    for (const child of node.children) {
      sortChildren(child);
    }
  }
  rootDocs.sort((a, b) => a.title.localeCompare(b.title));
  for (const root of rootDocs) {
    sortChildren(root);
  }

  // Render YAML manually (no YAML lib in n8n sandbox)
  function renderNode(node, indent) {
    const state = stateMap[node.id] || {};
    const file = state.file_path ? state.file_path.replace(/^Wiki\//, '') : '';
    const confluenceId = state.confluence_page_id || '';
    const escapedTitle = node.title.replace(/"/g, '\\"');

    let yaml = `${indent}- file: "${file}"\n`;
    yaml += `${indent}  title: "${escapedTitle}"\n`;
    yaml += `${indent}  confluence_id: "${confluenceId}"\n`;
    yaml += `${indent}  outline_id: "${node.id}"\n`;

    if (node.children.length > 0) {
      yaml += `${indent}  children:\n`;
      for (const child of node.children) {
        yaml += renderNode(child, indent + '    ');
      }
    }
    return yaml;
  }

  let yaml = '# Auto-generated by WF20 — maps Wiki/ files to Outline/Confluence hierarchy\n';
  yaml += '# Nested folder structure: parent docs = _index.md, leaf docs = Title.md\n';
  yaml += 'tree:\n';
  for (const root of rootDocs) {
    yaml += renderNode(root, '  ');
  }

  return yaml;
}

// --- Commit _tree.yaml to GitHub ---
async function commitTreeYaml(treeContent) {
  const treePath = 'Wiki/_tree.yaml';
  const encodedPath = encodeURIComponent(treePath).replace(/%2F/g, '/');

  // Get current SHA if file exists
  const currentFile = await ghApi(`/repos/${repo}/contents/${encodedPath}?ref=main`);
  const currentSha = currentFile.status === 200 ? currentFile.data?.sha : null;

  const content64 = Buffer.from(treeContent).toString('base64');
  const commitBody = {
    message: '[sync] Update _tree.yaml',
    content: content64
  };
  if (currentSha) commitBody.sha = currentSha;

  const resp = await ghApi(`/repos/${repo}/contents/${encodedPath}`, 'PUT', commitBody);
  return resp.status === 200 || resp.status === 201;
}

// --- Embed document and return qdrant point IDs ---
async function embedDoc(docText, docTitle, filePath, docId) {
  const chunks = chunkText(docText);
  const newQdrantIds = [];
  for (let i = 0; i < chunks.length; i++) {
    const chunkId = uuid();
    const vector = await embed(chunks[i]);
    if (vector) {
      await qdrantUpsert(chunkId, vector, {
        source: 'outline_sync',
        agent_id: AGENT_ID,
        repo,
        file_path: filePath,
        title: docTitle,
        chunk_index: i,
        total_chunks: chunks.length,
        content: chunks[i].substring(0, 500),
        outline_doc_id: docId,
        synced_at: new Date().toISOString()
      });
      newQdrantIds.push(chunkId);
    }
  }
  return { ids: newQdrantIds, chunks: chunks.length };
}

// --- Delete old qdrant points for a doc ---
async function deleteOldQdrant(escapedDocIdVal) {
