// --- Collect descendant doc IDs for subtree operations ---
async function collectDescendants(parentDocIdVal) {
  const escapedRepo = repo.replace(/'/g, "''");
  const escapedPid = parentDocIdVal.replace(/'/g, "''");
  const rows = await dbQuery(
    `SELECT outline_doc_id, file_path FROM sync_state WHERE repo = '${escapedRepo}' AND outline_parent_doc_id = '${escapedPid}'`
  );
  let descendants = [];
  if (rows && rows.trim()) {
    for (const row of rows.split('\n')) {
      if (!row.trim()) continue;
      const [oid, fp] = row.split('|');
      if (oid && fp) {
        descendants.push({ doc_id: oid.trim(), file_path: fp.trim() });
        // Recurse for children of children
        const subDesc = await collectDescendants(oid.trim());
        descendants = descendants.concat(subDesc);
      }
    }
  }
  return descendants;
}

